泛型是 C# 2.0 引入的重要特性，它提供了类型安全的代码重用机制。C# 4.0 进一步引入了协变和逆变，增强了泛型的灵活性。


## 泛型基础

泛型允许我们定义类型参数化的类、接口、方法和委托：
```csharp
// 泛型类
public class Repository<T>
{
    private readonly List<T> _items = new List<T>();

    public void Add(T item) => _items.Add(item);
    public T GetById(int id) => _items[id];
}

// 泛型方法
public T Max<T>(T a, T b) where T : IComparable<T>
{
    return a.CompareTo(b) > 0 ? a : b;
}
```

## 泛型缓存

泛型的一个重要应用是类型特定的缓存：

```csharp
public static class GenericCache<T>
{
    public static readonly T Value;

    static GenericCache()
    {
        // 每个类型参数 T 都有独立的静态字段
        Value = CreateValue();
    }
}

// 使用
var intValue = GenericCache<int>.Value;
var stringValue = GenericCache<string>.Value;
```

**应用场景**：
1. 类型特定的单例
2. 类型映射缓存
3. 反射结果缓存
4. 序列化器缓存


## 协变逆变的实际应用

**IEnumerable<T> 协变**：
```csharp
public interface IEnumerable<out T> : IEnumerable
{
    IEnumerator<T> GetEnumerator();
}
```

**Action<T> 逆变**：
```csharp
public delegate void Action<in T>(T obj);
```

**Func<TResult> 协变，Func<T> 逆变**：
```csharp
public delegate TResult Func<in T, out TResult>(T arg);
```

**自定义协变接口**：
```csharp
public interface IRepository<out T>
{
    T GetById(int id);
    IEnumerable<T> GetAll();
    // void Add(T item); // 错误：out 参数不能作为输入
}
```


## 泛型的性能优势

1. **类型安全**：编译时检查类型，避免运行时转换错误
2. **避免装箱**：值类型不需要装箱为 object
3. **代码重用**：一份代码支持多种类型
4. **更好的性能**：JIT 可以为值类型生成专门的代码

using System;
using System.Collections.Generic;

namespace GenericsVarianceDemo
{
    // 基类和派生类
    public class Animal
    {
        public string Name { get; set; }
        public virtual void Speak() => Console.WriteLine("...");
    }

    public class Dog : Animal
    {
        public override void Speak() => Console.WriteLine("Woof!");
    }

    public class Cat : Animal
    {
        public override void Speak() => Console.WriteLine("Meow!");
    }

    // 泛型约束示例
    public interface IEntity
    {
        int Id { get; set; }
    }

    public class EntityRepository<T> where T : class, IEntity, new()
    {
        private readonly Dictionary<int, T> _store = new Dictionary<int, T>();

        public void Add(T entity)
        {
            _store[entity.Id] = entity;
        }

        public T GetById(int id)
        {
            return _store.TryGetValue(id, out var entity) ? entity : null;
        }

        public T CreateNew()
        {
            return new T(); // 可以调用无参构造函数
        }
    }

    // 协变接口
    public interface IRepository<out T>
    {
        T GetById(int id);
        IEnumerable<T> GetAll();
    }

    // 逆变接口
    public interface IProcessor<in T>
    {
        void Process(T item);
    }

    // 实现协变接口
    public class AnimalRepository : IRepository<Animal>
    {
        private readonly List<Animal> _animals = new List<Animal>();

        public Animal GetById(int id) => _animals[id];
        public IEnumerable<Animal> GetAll() => _animals;
    }

    // 实现逆变接口
    public class AnimalProcessor : IProcessor<Animal>
    {
        public void Process(Animal item)
        {
            item.Speak();
        }
    }

    // 泛型缓存
    public static class TypeCache<T>
    {
        public static readonly string TypeName;
        public static readonly Type Type;
        public static readonly bool IsValueType;

        static TypeCache()
        {
            Type = typeof(T);
            TypeName = Type.Name;
            IsValueType = Type.IsValueType;
        }
    }

    // 泛型方法约束
    public static class MathHelper
    {
        public static T Max<T>(T a, T b) where T : IComparable<T>
        {
            return a.CompareTo(b) > 0 ? a : b;
        }

        public static T Create<T>() where T : new()
        {
            return new T();
        }
    }

    // 多约束示例
    public class Service<T> where T : class, IDisposable, IComparable<T>
    {
        public void DoWork(T item)
        {
            // T 必须是引用类型，实现 IDisposable 和 IComparable<T>
            item.CompareTo(item);
        }
    }

    class Program
    {
        static void Main()
        {
            // 泛型约束示例
            var dogRepo = new EntityRepository<Dog>();
            var dog = new Dog { Id = 1, Name = "Buddy" };
            dogRepo.Add(dog);

            // 协变示例
            IRepository<Dog> dogRepository = new AnimalRepository(); // 错误：Dog 不是 Animal
            IRepository<Animal> animalRepository = new AnimalRepository();

            // 协变赋值
            IEnumerable<Dog> dogs = new List<Dog>();
            IEnumerable<Animal> animals = dogs; // 合法

            // 逆变示例
            IProcessor<Animal> animalProcessor = new AnimalProcessor();
            IProcessor<Dog> dogProcessor = animalProcessor; // 合法

            dogProcessor.Process(new Dog()); // 调用 AnimalProcessor.Process

            // 泛型缓存使用
            Console.WriteLine(TypeCache<int>.TypeName); // Int32
            Console.WriteLine(TypeCache<string>.TypeName); // String
            Console.WriteLine(TypeCache<int>.IsValueType); // True
            Console.WriteLine(TypeCache<string>.IsValueType); // False

            // 泛型方法
            int maxInt = MathHelper.Max(10, 20);
            string maxString = MathHelper.Max("apple", "banana");

            // Func 委托的协变逆变
            Func<Dog, Animal> dogToAnimal = d => d;
            Func<Dog, Dog> dogToDog = dogToAnimal; // Func 逆变 T，协变 TResult
        }
    }
}
